beforeExample:
public class EncodingUser {
    public void someMethod() {
        String defaultEncoding = System.getProperty("file.encoding");
        System.out.println("Default encoding: " + defaultEncoding);
    }
}

afterExample:
import org.eclipse.core.runtime.Platform;

public class EncodingUser {
    public void someMethod() {
        String defaultEncoding = Platform.getSystemCharset().name();
        System.out.println("Default encoding: " + defaultEncoding);
    }
}

negativeExample:
public class OtherPropertyUser {
    public void anotherMethod() {
        String userHome = System.getProperty("user.home"); // Different property, should not match
        System.out.println("User home: " + userHome);
    }
}
